export default async function Page() {
  // Both fetches must finish BEFORE any HTML is written to the
  // response. If getComments takes 2s, the shell (header, nav,
  // above-the-fold content) waits 2s too: TTFB == slowest dep.
  const [posts, comments] = await Promise.all([getPosts(), getComments()]);

  return (
    <main>
      <Header />
      <Feed posts={posts} comments={comments} />
    </main>
  );
}

import { Suspense } from 'react';

async function Feed() {
  // Suspended inside the boundary: the shell streams instantly,
  // and this section's HTML is flushed into the response when
  // its promises resolve.
  const [posts, comments] = await Promise.all([getPosts(), getComments()]);
  return <FeedView posts={posts} comments={comments} />;
}

export default function Page() {
  return (
    <main>
      <Header />
      <Suspense fallback={<FeedSkeleton />}>
        <Feed />
      </Suspense>
    </main>
  );
}

// The shell (Header + main markup) reaches the browser first;
// the Feed section streams in after, replacing the skeleton.
